    const endPart = tab.slice(pivotIndex);

    // 2. Prendre les premiers N - 'effectiveK' éléments (qui forment la fin).
    const startPart = tab.slice(0, pivotIndex);

    // Concaténer les deux parties pour obtenir le tableau tourné.
    return endPart.concat(startPart);
