/**
 * Rotatise un tableau vers la droite de K positions.
 * @param {Array<any>} tab - Le tableau à faire pivoter.
 * @param {number} k - Le nombre de positions de rotation.
 * @returns {Array<any>} Le nouveau tableau pivoté.
 */
function rotationDroite(tab, k) {
    const n = tab.length;

    if (n === 0 || k % n === 0) {
        return [...tab]; // Retourne une copie si le tableau est vide ou la rotation est un multiple de N
    }

    // Calculer l'équivalent réel de K pour éviter des rotations inutiles.
