    // 1. Les K derniers éléments : tab.slice(n - effectiveK)
    const rotatedPart = tab.slice(n - effectiveK);

    // 2. Les N-K premiers éléments : tab.slice(0, n - effectiveK)
    const remainingPart = tab.slice(0, n - effectiveK);

    // Retourner le nouveau tableau combiné
    return [...rotatedPart, ...remainingPart];
}
