 * Pour une longueur paire, c'est la moyenne des deux éléments du milieu.
 * @param {number[]} tab - Le tableau de nombres d'entrée.
 * @returns {number} La médiane.
 */
function mediane(tab) {
    if (!Array.isArray(tab) || tab.length === 0) return NaN;

    // 1. Trier le tableau numériquement (crucial pour la médiane)
    const sortedTab = [...tab].sort((a, b) => a - b);
    const length = sortedTab.length;
    const middleIndex = Math.floor(length / 2);

    if (length % 2 === 1) {
        // Longueur impaire : retour de l'élément central
        return sortedTab[middleIndex];
    } else {
        // Longueur paire : moyenne des deux éléments centraux
        const lowerMiddle = sortedTab[middleIndex - 1];
        const upperMiddle = sortedTab[middleIndex];
        return (lowerMiddle + upperMiddle) / 2;
    }
}
