    const phrases = texte.split('.').filter(segment => segment.trim().length > 0);

    return phrases.length === nbPhrases;
}

/**
 * Valide si les parenthèses dans une chaîne sont équilibrées (uniquement '(' et ')').
 * @param {string} s La chaîne de caractères à vérifier.
 * @returns {boolean} True si elles sont valides, false sinon.
 */
function validerParentheses(s) {
    let balance = 0;
    for (const char of s) {
        if (char === '(') {
            balance++;
        } else if (char === ')') {
            balance--;
        }

        // Si le compteur devient négatif, cela signifie qu'une parenthèse fermante est apparue sans ouverture correspondante.
        if (balance < 0) {
            return false;
        }
    }
    // Pour être valide, la balance doit être exactement zéro à la fin.
    return balance === 0;
}

/**
 * Calcule le n-ième nombre de Fibonacci (F(0)=0, F(1)=1).
 * @param {number} n L'indice du nombre de Fibonacci à calculer.
 * @returns {number} Le n-ième nombre de Fibonacci.
 */
function fibonacci(n) {
    if (n < 0) return undefined; // Gestion d'entrée non valide
    if (n === 0) return 0;
    if (n === 1) return 1;

    let a = 0; // F(i-2)
    let b = 1; // F(i-1)
    let result = 0;

    // On commence à i=2 car F(0) et F(1) sont déjà définis.
    for (let i = 2; i <= n; i++) {
        result = a + b;
        a = b; // L'ancien F(i-1) devient le nouveau F(i-2)
        b = result; // Le résultat actuel devient le nouveau F(i-1)
    }
    return result;
}

/**
 * Compte le nombre de mots uniques dans une chaîne, en ignorant la casse.
 * @param {string} s La chaîne contenant les mots séparés par des espaces.
 * @returns {number} Le nombre de mots distincts.
 */
function motsUniques(s) {
    // 1. Séparer la chaîne par n'importe quel espace (regex /\s+/).
    // 2. Filtrer pour retirer les chaînes vides qui pourraient résulter des espaces multiples ou d'une entrée vide.
    const words = s.split(/\s+/).filter(word => word.length > 0);

    // 3. Convertir tous les mots en minuscules pour garantir l'unicité insensible à la casse.
    const uniqueWords = new Set(words.map(word => word.toLowerCase()));

    return uniqueWords.size;
}

/**
 * Aplatit un tableau de tableaux par un seul niveau (e.g., [[1,2],[3]] -> [1,2,3]).
 * @param {Array<Array<any>>} tab Le tableau imbriqué à aplatir.
 * @returns {Array<any>} Le tableau aplati.
 */
function aplatisTableau(tab) {
    // Utilisation de la méthode .flat() avec un facteur de 1 pour s'assurer que l'aplatissement est limité au premier niveau.
    return tab.flat(1);

    /* Alternative utilisant reduce et concat (si flat n'était pas disponible):
    return tab.reduce((acc, currentArray) => acc.concat(currentArray), []);
    */
}

/**
 * Effectue une rotation à droite sur un tableau par k positions.
 * @param {Array<any>} tab Le tableau original.
 * @param {number} k Le nombre de positions de rotation.
 * @returns {Array<any>} Le nouveau tableau rotaté.
 */
function rotationDroite(tab, k) {
    const n = tab.length;
    if (n === 0 || k % n === 0) {
        return [...tab]; // Retourne une copie si pas de rotation nécessaire ou tableau vide
    }

    // Calculer le nombre effectif de rotations
    k = k % n;

    // La rotation à droite par k signifie que les k derniers éléments passent au début.
    // 1. Slice des k derniers éléments (qui deviennent le préfixe)
    const endPart = tab.slice(n - k);
    // 2. Slice des N-k premiers éléments (qui forment la suite)
    const startPart = tab.slice(0, n - k);

    // Concaténer les deux parties
    return [...endPart, ...startPart];
}

