/**
 * Calcule la moyenne pondérée d'un ensemble de notes.
 * @param {Array<{valeur: number, coeff: number}>} notes - Tableau des objets note/coefficient.
 * @returns {number} La moyenne pondérée ou 0 si le tableau est vide.
 */
function moyennePonderee(notes) {
    if (!notes || notes.length === 0) {
        return 0;
    }

    let sommeProduits = 0;
    let sommeCoefficients = 0;

    for (const note of notes) {
        sommeProduits += note.valeur * note.coeff;
        sommeCoefficients += note.coeff;
    }

    if (sommeCoefficients === 0) {
        return 0; // Évite la division par zéro si tous les coefficients sont nuls
    }

    return sommeProduits / sommeCoefficients;
}
