/**
 * @description Trie un tableau de nombres par ordre croissant sans utiliser Array.prototype.sort().
 * Implémente l'algorithme du Tri à Bulles (Bubble Sort).
 * Complexité temporelle: O(N^2).
 * @param {number[]} arr - Le tableau de nombres à trier.
 * @returns {number[]} Le tableau trié.
 */
function trier_tableau(arr) {
    const n = arr.length;
    // Créer une copie pour ne pas modifier le tableau original (bonne pratique d'ingénierie)
    const sortedArr = [...arr]; 

    for (let i = 0; i < n - 1; i++) {
        let swapped = false;
        for (let j = 0; j < n - 1 - i; j++) {
            if (sortedArr[j] > sortedArr[j + 1]) {
                // Échange des éléments
                [sortedArr[j], sortedArr[j + 1]] = [sortedArr[j + 1], sortedArr[j]];
                swapped = true;
            }
        }
        // Optimisation: si aucun échange n'a eu lieu, le tableau est trié
        if (!swapped) {
            break;
        }
    }
    return sortedArr;
}
