 * Implémente une solution efficace en O(log(min(m, n))) sans fusionner les tableaux.
 * @param {number[]} a - Premier tableau trié.
 * @param {number[]} b - Deuxième tableau trié.
 * @returns {number} La médiane combinée.
 */
function medianeDeuxTries(a, b) {
    // Assurer que A est le plus petit des deux tableaux pour optimiser la recherche binaire
    if (a.length > b.length) {
        return medianeDeuxTries(b, a);
    }

    const m = a.length;
    const n = b.length;
    // La taille totale de la partition désirée est (m + n + 1) / 2
    let low = 0;
    let high = m;

    while (low <= high) {
        // Partitionnement dans A et B
        const partitionA = Math.floor((low + high) / 2);
        const partitionB = Math.floor((m + n + 1) / 2) - partitionA;

        // Définir les valeurs de bordure (handling edge cases with Infinity)
        const maxLeftA = (partitionA === 0) ? Number.NEGATIVE_INFINITY : a[partitionA - 1];
        const minRightA = (partitionA === m) ? Number.POSITIVE_INFINITY : a[partitionA];

        const maxLeftB = (partitionB === 0) ? Number.NEGATIVE_INFINITY : b[partitionB - 1];
        const minRightB = (partitionB === n) ? Number.POSITIVE_INFINITY : b[partitionB];

        // Condition de partition correcte: Max du côté gauche <= Min du côté droit
        if (maxLeftA <= minRightB && maxLeftB <= minRightA) {
            // Partition trouvée ! Calculer la médiane.
            const totalLength = m + n;
            if (totalLength % 2 === 1) {
                // Nombre impair de éléments: la médiane est le plus grand élément du côté gauche
                return Math.max(maxLeftA, maxLeftB);
            } else {
                // Nombre pair d'éléments: moyenne des deux éléments centraux
                const leftMax = Math.max(maxLeftA, maxLeftB);
                const rightMin = Math.min(minRightA, minRightB);
                return (leftMax + rightMin) / 2;
            }
