    let i = 0; // Pointeur pour le tableau a
    let j = 0; // Pointeur pour le tableau b

    // Tant qu'il reste des éléments dans les deux tableaux
    while (i < a.length && j < b.length) {
        if (a[i] <= b[j]) {
            result.push(a[i]);
            i++;
        } else {
            result.push(b[j]);
            j++;
        }
