```javascript
/**
 * Tri sorts an array of numbers in ascending order without using Array.prototype.sort().
 * Implements Insertion Sort for stability and simplicity.
 * @param {number[]} arr The array to sort.
 * @returns {number[]} The sorted array.
 */
function trier_tableau(arr) {
    const n = arr.length;
    for (let i = 1; i < n; i++) {
        let current = arr[i];
        let j = i - 1;

        // Move elements of arr[0..i-1] that are greater than current
        // to one position ahead of their current position.
        while (j >= 0 && arr[j] > current) {
            arr[j + 1] = arr[j];
            j--;
        }
        arr[j + 1] = current;
    }
    return arr;
}
