/**
 * Finds the median of two sorted arrays A and B in O(log(min(m, n))) time complexity.
 * This uses the binary search approach to find the correct partition.
 * @param {number[]} a First sorted array.
 * @param {number[]} b Second sorted array.
 * @returns {number} The median of the combined arrays.
 */
function medianeDeuxTries(a, b) {
    // Ensure A is the smaller array for complexity optimization O(log(min(m, n)))
    if (a.length > b.length) {
        return medianeDeuxTries(b, a);
    }

    const m = a.length;
    const n = b.length;
    // Total elements needed on the left side of the partition
    const halfLen = Math.floor((m + n + 1) / 2);

    let low = 0;
    let high = m; // Search space for partition in A (i)

    while (low <= high) {
        // i is the cut point in array A, j is the cut point in array B
        const i = Math.floor((low + high) / 2);
        const j = halfLen - i;

        // Define boundary elements for comparison
        // Use -Infinity and Infinity to handle edge cases where i or j are 0 or length
        const aLeftMax = (i === 0) ? Number.NEGATIVE_INFINITY : a[i - 1];
        const aRightMin = (i === m) ? Number.POSITIVE_INFINITY : a[i];

        const bLeftMax = (j === 0) ? Number.NEGATIVE_INFINITY : b[j - 1];
        const bRightMin = (j === n) ? Number.POSITIVE_INFINITY : b[j];

        // Check if the partition is correct:
        // 1. Max element on left side of A <= Min element on right side of B
        // 2. Max element on left side of B <= Min element on right side of A
        if (aLeftMax <= bRightMin && bLeftMax <= aRightMin) {
            // Partition found! Calculate the median.

            if ((m + n) % 2 === 1) {
                // Odd total length: Median is the maximum of the left halves
                return Math.max(aLeftMax, bLeftMax);
            } else {
                // Even total length: Median is the average of the two middle elements
                const leftMax = Math.max(aLeftMax, bLeftMax);
                const rightMin = Math.min(aRightMin, bRightMin);
                return (leftMax + rightMin) / 2;
