/**
 * Finds the length of the Longest Strictly Increasing Subsequence (LIS).
 * Uses an optimized O(N log N) approach based on patience sorting and binary search.
 * @param {number[]} tab Array of numbers.
 * @returns {number} The length of the LIS.
 */
function plusLongueSousSuiteCroissante(tab) {
    if (!tab || tab.length === 0) {
        return 0;
    }

    // 'tails' stores the smallest tail element among all increasing subsequences
    // with a length equal to its index + 1.
    const tails = [];

    /**
     * Binary search helper function (finds the ceiling/insertion point).
     * Finds the smallest element in 'arr' that is >= target.
     * @param {number[]} arr The sorted array (tails).
     * @param {number} target The value to search for.
     * @returns {number} The index where the target should be placed/replaced.
     */
    const binarySearchCeiling = (arr, target) => {
        let left = 0;
        let right = arr.length - 1;
        let resultIndex = arr.length; // Default: append to end

        while (left <= right) {
            const mid = Math.floor((left + right) / 2);
            if (arr[mid] >= target) {
                // This could be the ceiling, try for an even smaller index
                resultIndex = mid;
                right = mid - 1;
            } else {
                // Target is larger, search in the right half
                left = mid + 1;
            }
        }
        return resultIndex;
    };

    for (const num of tab) {
        // Find the index 'i' where tails[i] is the smallest element >= num.
        const i = binarySearchCeiling(tails, num);

        if (i === tails.length) {
            // If num is larger than all current tails, it extends the longest subsequence found so far.
            tails.push(num);
        } else {
            // Otherwise, we found a smaller tail for an existing length i+1 subsequence.
            // This allows future numbers to extend this sequence more easily.
            tails[i] = num;
        }
    }

    // The length of the 'tails' array is the length of the LIS.
    return tails.length;
}
